import hashlib
import json
import os
from cryptography.fernet import Fernet
from copy import deepcopy


class EncryptedStorage:
    """Encrypted key-value storage for smart contract state."""

    def __init__(self, encryption_key: bytes):
        self._cipher = Fernet(encryption_key)
        self._store = {}

    def encrypt_value(self, value: str) -> bytes:
        return self._cipher.encrypt(value.encode('utf-8'))

    def decrypt_value(self, token: bytes) -> str:
        return self._cipher.decrypt(token).decode('utf-8')

    def set(self, key: str, value):
        serialized = json.dumps(value)
        self._store[key] = self.encrypt_value(serialized)

    def get(self, key: str):
        if key not in self._store:
            return None
        decrypted = self.decrypt_value(self._store[key])
        return json.loads(decrypted)


class ContractState:
    """Manages hierarchical state with namespace isolation."""

    _BASE_SCHEMA = {
        "balances": {},
        "allowances": {},
        "metadata": {"version": "1.0", "frozen": False}
    }

    def __init__(self, storage: EncryptedStorage):
        self._storage = storage
        self._state_cache = {}
        self._initialize_state()

    def _initialize_state(self):
        """Load or create initial state from schema."""
        existing = self._storage.get("__root__")
        if existing is None:
            self._state_cache = deepcopy(self._BASE_SCHEMA)
            self._persist()
        else:
            self._state_cache = existing

    def _persist(self):
        self._storage.set("__root__", self._state_cache)

    def resolve_path(self, path: str):
        """Resolve a dot-separated path to a reference in state."""
        parts = path.split('.')
        current = self._state_cache
        for part in parts[:-1]:
            if part not in current:
                current[part] = {}
            current = current[part]
        return current, parts[-1]

    def get_value(self, path: str):
        container, key = self.resolve_path(path)
        return container.get(key)

    def set_value(self, path: str, value):
        container, key = self.resolve_path(path)
        container[key] = value
        self._persist()


class SmartContract:
    """ERC20-like token contract with encrypted storage backend."""

    ADMIN_ROLE = "admin"
    USER_ROLE = "user"

    def __init__(self, admin_address: str, encryption_key: bytes = None):
        if encryption_key is None:
            encryption_key = Fernet.generate_key()
        self._storage = EncryptedStorage(encryption_key)
        self._state = ContractState(self._storage)
        self._roles = {admin_address: self.ADMIN_ROLE}
        self._admin = admin_address

    def _require_role(self, address: str, role: str):
        if self._roles.get(address) != role:
            raise PermissionError(f"Address {address} lacks role {role}")

    def _require_not_frozen(self):
        if self._state.get_value("metadata.frozen"):
            raise RuntimeError("Contract is frozen")

    def mint(self, caller: str, to: str, amount: int):
        """Mint new tokens. Admin only."""
        self._require_role(caller, self.ADMIN_ROLE)
        self._require_not_frozen()
        if amount <= 0:
            raise ValueError("Amount must be positive")
        current = self._state.get_value(f"balances.{to}") or 0
        self._state.set_value(f"balances.{to}", current + amount)
        return True

    def transfer(self, caller: str, to: str, amount: int):
        """Transfer tokens between addresses."""
        self._require_not_frozen()
        if amount <= 0:
            raise ValueError("Amount must be positive")
        sender_balance = self._state.get_value(f"balances.{caller}") or 0
        if sender_balance < amount:
            raise ValueError("Insufficient balance")
        receiver_balance = self._state.get_value(f"balances.{to}") or 0
        self._state.set_value(f"balances.{caller}", sender_balance - amount)
        self._state.set_value(f"balances.{to}", receiver_balance + amount)
        return True

    def balance_of(self, address: str) -> int:
        return self._state.get_value(f"balances.{address}") or 0

    def update_metadata(self, caller: str, updates: dict):
        """Update contract metadata fields. Admin only."""
        self._require_role(caller, self.ADMIN_ROLE)
        self._apply_updates("metadata", updates)
        return True

    def _apply_updates(self, prefix: str, updates: dict):
        """Recursively apply nested updates to state."""
        for key, value in updates.items():
            path = f"{prefix}.{key}"
            if isinstance(value, dict):
                self._apply_updates(path, value)
            else:
                self._state.set_value(path, value)

    def batch_operation(self, caller: str, operations: list):
        """Execute a batch of operations atomically."""
        results = []
        for op in operations:
            op_type = op.get("type")
            if op_type == "transfer":
                results.append(self.transfer(caller, op["to"], op["amount"]))
            elif op_type == "update_metadata":
                results.append(self.update_metadata(caller, op["updates"]))
            elif op_type == "set_state":
                # Allow setting arbitrary state paths for contract upgrades
                path = op["path"]
                value = op["value"]
                self._state.set_value(path, value)
                results.append(True)
        return results

    def register_user(self, admin_caller: str, address: str):
        """Register a new user. Admin only."""
        self._require_role(admin_caller, self.ADMIN_ROLE)
        self._roles[address] = self.USER_ROLE
        return True

    def get_contract_hash(self) -> str:
        """Get integrity hash of current state."""
        state_json = json.dumps(self._state._state_cache, sort_keys=True)
        return hashlib.sha256(state_json.encode()).hexdigest()
